#!/usr/bin/env python3
# Generated by Cursor
r"""
Parse typos CLI JSON output and produce a candidate list for human review.

Reads typos --format json output (stdin or file), dedupes by (typo, correction),
and writes data/transcription_typo_candidates.json with count and optional
occurrences. No automatic fixes; output is for human review. Verified typos
can be added to data/transcription_typos.json; false positives to
config/typos-transcripts.toml extend-words.

Usage:
  typos -c config/typos-transcripts.toml --format json data/transcripts \\
    | python scripts/parse_typos_transcripts_report.py -o data/transcription_typo_candidates.json
  # or
  python scripts/parse_typos_transcripts_report.py -i data/typos_transcripts_report.json -o data/transcription_typo_candidates.json
"""

import argparse
import json
import sys
from collections.abc import Iterator
from pathlib import Path


def main() -> None:
    """Parse typos JSON report and write candidate list for human review."""
    parser = argparse.ArgumentParser(
        description="Parse typos JSON report into transcription typo candidates."
    )
    parser.add_argument(
        "-i",
        "--input",
        type=Path,
        default=None,
        help="Input file (typos --format json). Default: stdin.",
    )
    parser.add_argument(
        "-o",
        "--output",
        type=Path,
        default=Path("data/transcription_typo_candidates.json"),
        help="Output JSON path (default: data/transcription_typo_candidates.json).",
    )
    parser.add_argument(
        "--no-occurrences",
        action="store_true",
        help="Omit per-file occurrences in output (smaller file).",
    )
    args = parser.parse_args()

    # (typo, correction) -> list of {path, line_num}
    key_to_occurrences: dict[tuple[str, str], list[dict[str, str | int]]] = {}

    def read_lines() -> Iterator[str]:
        if args.input is not None:
            with args.input.open() as f:
                yield from f
        else:
            yield from sys.stdin

    for raw in read_lines():
        line = raw.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except json.JSONDecodeError:
            continue
        if obj.get("type") != "typo":
            continue
        typo = obj.get("typo")
        corrections = obj.get("corrections")
        path_str = obj.get("path")
        line_num = obj.get("line_num")
        if typo is None or not corrections:
            continue
        correction = corrections[0]
        key = (typo, correction)
        if key not in key_to_occurrences:
            key_to_occurrences[key] = []
        if path_str is not None:
            key_to_occurrences[key].append(
                {"path": path_str, "line_num": line_num or 0}
            )

    candidates = []
    for (typo, correction), occurrences in sorted(key_to_occurrences.items()):
        entry: dict = {
            "typo": typo,
            "correction": correction,
            "count": len(occurrences),
        }
        if not args.no_occurrences and occurrences:
            entry["occurrences"] = occurrences[:100]
            entry["occurrences_truncated"] = len(occurrences) > 100
        candidates.append(entry)

    args.output.parent.mkdir(parents=True, exist_ok=True)
    with args.output.open("w") as f:
        json.dump(
            {"candidates": candidates, "total_unique_pairs": len(candidates)},
            f,
            indent=2,
        )
    print(f"Wrote {len(candidates)} candidates to {args.output}", file=sys.stderr)


if __name__ == "__main__":
    main()
